"""🖼️ Figurinhas das palavras difíceis do 2º bimestre de 2027 (6º ao 9º ano), 21/11/2026. Desenhos em linha clara
feitos pelo Claude. Importado por termos.py. Sem fotos de pessoas: Grace Hopper aparece pela história da mariposa."""
from linha_clara import V, K, t, r, c, p, etiqueta, seta_grossa, seta_baixo
from termos_2027_1bim import kj, cel, fila, no, lig, blk, seta, emo, arvore_mini, grafo_mini


def registrar(d, D, kp):
    pulados = []
    def dd(nomes, rot, corpo, cor="cinza"):
        novos = [n for n in nomes.split("|") if kp(n) not in D and kj(n) not in D]
        pulados.extend(n for n in nomes.split("|") if n not in novos)
        if not novos: return
        d("|".join(novos), rot, corpo, cor)
        for n in novos: D[kj(n)] = D[kp(n)]
    registrar.pulados = pulados
    lst = lambda x, y, itens, cor="azul": r(x, y, 200, 26 * len(itens) + 16, "#fff", rx=8, lw=3, sombra=3) + "".join(t(x + 16, y + 30 + i * 26, s, 14, K, 800, "start") for i, s in enumerate(itens))
    # ---------- 6º ano · algoritmos ----------
    dd("passo|passos", "Passo: cada parte do algoritmo, uma de cada vez", "".join(r(40 + i * 82, 140 - i * 34, 80, 34 + i * 34, V["azul"][1], rx=4, lw=3) + t(80 + i * 82, 162, f"{i + 1}º", 16, K, 900) for i in range(3)), "azul")
    dd("preciso|precisa", "Preciso: diz exatamente o que fazer (2 colheres, e não “um pouco”)", r(40, 50, 110, 80, "#dcfce7", rx=10, lw=3, sombra=3) + t(95, 86, "2 colheres", 15, K, 900) + t(95, 112, "✔ preciso", 13, "verde", 900) + r(170, 50, 110, 80, "#fee2e2", rx=10, lw=3, sombra=3) + t(225, 86, "um pouco", 15, K, 900) + t(225, 112, "✘ vago", 13, "vermelho", 900), "verde")
    dd("resultado", "Resultado: o que se consegue no fim do algoritmo", blk(40, 50, "passo 1", "azul", 90) + blk(40, 90, "passo 2", "azul", 90) + blk(40, 130, "passo 3", "azul", 90) + seta_grossa(150, 105, 196, "verde", 24) + emo(250, 120, "🎂", 54), "verde")
    dd("ordem", "Ordem: qual passo vem primeiro, segundo, terceiro…", "".join(cel(50 + i * 80, 70, f"{i + 1}º", "#fff", 60, 50, 20) for i in range(3)) + emo(80, 160, "🧦", 26) + emo(160, 160, "👟", 26) + t(230, 166, "meia antes!", 13, K, 900), "amarelo")
    dd("labirinto", "Labirinto: caminho cheio de corredores, paredes e becos", "".join(r(60 + (i % 5) * 40, 30 + (i // 5) * 36, 40, 36, V["cinza"][0] if i in (1, 3, 6, 8, 13, 16, 18) else "#fff", rx=2, lw=2) for i in range(20)) + t(80, 56, "🤖", 22) + t(240, 164, "⭐", 22), "cinza")
    dd("repita", "Repita: faz o mesmo comando várias vezes", blk(40, 60, "repita 4× ➡️", "amarelo", 170, 40, 17) + "".join(t(70 + i * 40, 150, "➡️", 22) for i in range(4)), "amarelo")
    dd("laco infinito|loop", "Laço infinito: repetição que nunca para e trava o programa", p("M110 100 C 110 40, 210 40, 210 100 C 210 160, 110 160, 110 100", "none", 7) + t(160, 112, "∞", 46, "vermelho", 900) + etiqueta(160, 182, "trava!", "vermelho", 12), "vermelho")
    dd("padrao", "Padrão: algo que se repete sempre do mesmo jeito", "".join(c(50 + i * 36, 100, 14, "#111" if i % 3 == 2 else "#fff", 3) for i in range(7)) + etiqueta(160, 160, "⚪⚪⚫ ⚪⚪⚫…", "roxo", 12), "roxo")
    dd("se… então… senão|se entao senao", "Se… então… senão: escolhe um caminho pela resposta sim ou não", blk(110, 30, "Está chovendo?", "roxo", 140) + lig(180, 62, 90, 110) + lig(180, 62, 260, 110) + t(118, 88, "sim", 13, "verde", 900) + t(240, 88, "não", 13, "vermelho", 900) + emo(90, 140, "☂️", 38) + emo(260, 140, "🧢", 38), "roxo")
