    dd("equipe", "Equipe: um grupo que trabalha junto, cada um com a sua parte", emo(90, 110, "🧑", 44) + emo(160, 100, "👩", 44) + emo(230, 110, "🧒", 44) + etiqueta(160, 170, "trabalho junto", "verde", 12), "verde")
    dd("grace hopper", "Grace Hopper: cientista cuja equipe achou, em 1947, uma mariposa no computador: o “bug”", r(60, 30, 200, 130, "#fef3c7", rx=6, lw=3, sombra=3) + t(160, 60, "9/9/1947", 13, K, 800) + emo(160, 108, "🦋", 46) + t(160, 148, "primeiro “bug”", 13, K, 900), "amarelo")
