    dd("rede social", "Rede social: aplicativo em que as pessoas se ligam umas às outras", grafo_mini().replace("", "") , "azul")
    dd("soma dos pesos", "Soma dos pesos: quanto o caminho custa (3 + 2 = 5)", lig(60, 100, 160, 100, 3) + lig(160, 100, 260, 100, 2) + no(60, 100, "A") + no(160, 100, "B") + no(260, 100, "C") + etiqueta(160, 160, "3 + 2 = 5", "verde", 13), "verde")
    dd("somar|soma", "Somar: juntar os números (3 + 2 = 5)", t(160, 110, "3 + 2 = 5", 34, K, 900), "verde")
