    dd("cronograma", "Cronograma: o calendário com o que fazer em cada dia", "".join(cel(30 + i * 52, 60, d, "#fde68a" if i == 2 else "#fff", 48, 30, 12) for i, d in enumerate(["seg", "ter", "qua", "qui", "sex"])) + "".join(r(34 + i * 52, 98, 40, 12, V[cc][0], rx=4, lw=2) for i, cc in enumerate(["azul", "verde", "amarelo", "rosa", "roxo"])), "amarelo")
