    dd("mapa", "Mapa: desenho de um lugar visto de cima", r(50, 30, 220, 130, "#dcfce7", rx=6, lw=3) + p("M50 90 H270 M150 30 V160", "none", 6) + emo(100, 70, "🏫", 22) + emo(210, 130, "⛪", 22), "verde")
